const body = $input.first().json.body || $input.first().json;
const userId = body.user_id || body.userId || null;
const campaignId = body.campaign_id || body.campaignId || null;
const message = (body.message || body.text || '').trim();

if (!message) {
  throw new Error('Campo message obrigatório.');
}
if (!campaignId) {
  throw new Error('Campo campaign_id obrigatório.');
}

const requestId = 'req_' + Date.now() + '_' + Math.random().toString(36).substring(2, 8);
const startedAt = Date.now();

console.log('[NEXO Assistant] Request: ' + requestId + ' | User: ' + userId + ' | Campaign: ' + campaignId);
console.log('[NEXO Assistant] Mensagem: ' + message);

return [{
  json: {
    request_id: requestId,
    user_id: userId,
    campaign_id: campaignId,
    message,
    started_at: startedAt,
    timestamp: new Date().toISOString()
  }
}];

const input = $('Validar Entrada').first().json;
const aiItem = $('Classificar Intenção (OpenAI)').first();

let classification = {
  intent: 'GENERAL',
  sub_intent: 'consulta geral',
  sentiment_filter: 'all',
  time_range: '24h',
  entity_focus: null,
  content_type: null,
  urgency: 'medium',
  keywords: []
};

try {
  const raw = aiItem?.json?.message?.content || aiItem?.json?.choices?.[0]?.message?.content || '{}';
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  classification = { ...classification, ...JSON.parse(cleaned) };
} catch(e) {
  console.log('[NEXO Assistant] Fallback classificação: ' + e.message);
}

// --- Reforço determinístico da classificação ---
// O LLM erra entity_focus e time_range com frequência: "como está o Bruno Teles essa
// semana?" voltava como GENERAL/24h e a busca trazia loteria em vez do Bruno Teles.
// Casar o nome contra a lista monitorada e o período contra o texto é exato.
const _norm = s => (s || '').normalize('NFD').replace(/\p{Diacritic}/gu, '').toLowerCase();
const MONITORADOS = ['Ricardo Lima', 'Paulo Ferraz', 'Bruno Teles', 'Helena Braga', 'Jorge Braga', 'Otávio Pires', 'André Moraes', 'Sérgio Antunes', 'Clara Teles', 'Rui Matos', 'Lara Vieira'];
const _msg = _norm(input.message || '');
const _achado = MONITORADOS.find(n => _msg.includes(_norm(n)));
if (_achado) {
  classification.entity_focus = _achado;
  if (classification.intent === 'GENERAL') classification.intent = 'ADVERSARY';
}
if (/semana|7 dias/.test(_msg)) classification.time_range = '7d';
else if (/\bmes\b|\bmeses\b|30 dias/.test(_msg)) classification.time_range = '30d';

// Mapear time_range para SQL interval
const intervalMap = { '24h': '24 hours', '48h': '48 hours', '7d': '7 days', '30d': '30 days', 'all': '365 days' };
const sqlInterval = intervalMap[classification.time_range] || '24 hours';

console.log('[NEXO Assistant] Intenção: ' + classification.intent + ' | Sub: ' + classification.sub_intent);

return [{
  json: {
    ...input,
    classification,
    sql_interval: sqlInterval
  }
}];

const ctx = $('Processar Classificação').first().json;
const intent = ctx.classification.intent;
const sentimentFilter = ctx.classification.sentiment_filter;
const campaignId = ctx.campaign_id;
const interval = ctx.sql_interval;
const entityFocus = ctx.classification.entity_focus;

let sourceFilter = "AND TRUE";
if (intent === 'MEDIA') sourceFilter = "AND m.source = 'news'";
else if (intent === 'SOCIAL') sourceFilter = "AND m.source IN ('facebook', 'instagram', 'twitter', 'social')";
else if (intent === 'ADVERSARY') sourceFilter = "AND me.entity_type = 'opponent'";

let sentimentClause = "AND TRUE";
if (sentimentFilter === 'positive') sentimentClause = "AND m.sentiment = 'positive'";
else if (sentimentFilter === 'negative') sentimentClause = "AND m.sentiment = 'negative'";
else if (sentimentFilter === 'neutral') sentimentClause = "AND m.sentiment = 'neutral'";

let entityClause = "AND TRUE";
if (entityFocus) entityClause = `AND (me.name ILIKE '%${entityFocus.replace(/'/g, "''")}%' OR m.title ILIKE '%${entityFocus.replace(/'/g, "''")}%')`;

// RADAR varre o ciclo inteiro: com 30 itens o share of voice não fecha.
const limit = intent === 'RADAR' ? 150
  : (intent === 'INTELLIGENCE' || intent === 'STRATEGY') ? 50 : 30;

// COUNT(*) OVER() é avaliado antes do LIMIT: dá o volume real do período, não
// o tamanho do lote. No Radar, ordena por relevância — por recência pura o
// contexto enchia de resultado de loteria.
const orderBy = intent === 'RADAR'
  ? "ORDER BY (me.entity_type IN ('candidate','opponent')) DESC, (m.metadata->>'relevance_score')::numeric DESC NULLS LAST, m.created_at DESC"
  : 'ORDER BY m.created_at DESC';

const query = `SELECT m.id, m.source, m.title, m.content, m.sentiment, m.url, m.published_at, m.created_at, m.metadata, me.name as entity_name, me.entity_type, COUNT(*) OVER()::int AS total_periodo FROM mentions m LEFT JOIN monitored_entities me ON me.id = m.entity_id WHERE m.campaign_id = '${campaignId}' AND m.created_at >= NOW() - INTERVAL '${interval}' ${sourceFilter} ${sentimentClause} ${entityClause} ${orderBy} LIMIT ${limit}`;

console.log('[NEXO Assistant] Query menções: intent=' + intent);
return [{ json: { ...ctx, dynamic_query: query } }];

// Renomear um nó no canvas derrubava o Code inteiro com "Referenced node
// doesn't exist". Aceita os nomes do workflow original e os abreviados; nó
// ausente vira lista vazia, e só as menções são obrigatórias.
const pegar = (...nomes) => {
  for (const nome of nomes) {
    try {
      const r = $(nome).all();
      if (r && r.length) return r;
    } catch (e) { /* nó não existe neste workflow */ }
  }
  return [];
};

const ctx = pegar('Processar Classificação', 'Classificação')[0]?.json || {};
const campaignItems = pegar('Buscar Dados da Campanha', 'Buscar Campanha');
const reportItems = pegar('Buscar Relatórios de Inteligência', 'Buscar Relatório', 'Buscar Relatórios');
const alertItems = pegar('Buscar Alertas Ativos', 'Buscar Alertas');
const mentionItems = pegar('Buscar Menções Dinâmicas', 'Buscar Menções');
const entityItems = pegar('Buscar Entidades', 'Buscar Entidades Monitoradas');

const campaign = campaignItems[0]?.json || {};
const reports = reportItems.map(i => i.json);
const alerts = alertItems.map(i => i.json);
const mentions = mentionItems.map(i => i.json);
const entities = entityItems.map(i => i.json);

// --- Consolidar sentimento das menções ---
const sentCount = { positive: 0, neutral: 0, negative: 0 };
mentions.forEach(m => { const s = m.sentiment || 'neutral'; sentCount[s] = (sentCount[s] || 0) + 1; });
const total = mentions.length;

// --- Parsear ultimo relatório ---
let latestReport = null;
if (reports.length > 0) {
  try {
    const r = reports[0];
    const parsed = typeof r.content === 'string' ? JSON.parse(r.content) : r.content;
    latestReport = {
      title: r.title,
      created_at: r.created_at,
      summary: parsed.summary || '',
      risks: parsed.risks || [],
      opportunities: parsed.opportunities || [],
      themes_rising: parsed.themes_rising || [],
      themes_falling: parsed.themes_falling || [],
      insights: parsed.insights || [],
      recommendations: parsed.recommendations || [],
      agenda_suggestions: parsed.agenda_suggestions || [],
      adversary_movements: parsed.adversary_movements || [],
      crisis_alerts: parsed.crisis_alerts || [],
      sentiment_analysis: parsed.sentiment_analysis || {}
    };
  } catch(e) {
    latestReport = { title: reports[0]?.title || '', summary: 'Relatório disponível mas não parseável.', created_at: reports[0]?.created_at };
  }
}

// --- Montar bloco de contexto do relatório ---
let reportContext = 'Nenhum relatório de inteligência disponível.';
if (latestReport) {
  reportContext = `RELATÓRIO: ${latestReport.title} (${latestReport.created_at?.substring(0,16) || ''})

RESUMO EXECUTIVO:
${latestReport.summary}

TEMAS EM ALTA:
${latestReport.themes_rising?.map(t => `• ${t.theme}: ${t.reason} [${t.urgency}]`).join('\n') || 'Nenhum'}

TEMAS EM QUEDA:
${latestReport.themes_falling?.map(t => `• ${t.theme}: ${t.reason}`).join('\n') || 'Nenhum'}

RISCOS IDENTIFICADOS:
${latestReport.risks?.map(r => `• [${r.impact}] ${r.risk} → ${r.mitigation}`).join('\n') || 'Nenhum'}

OPORTUNIDADES:
${latestReport.opportunities?.map(o => `• ${o.opportunity} → ${o.action}`).join('\n') || 'Nenhuma'}

INSIGHTS:
${latestReport.insights?.join('\n• ') || 'Nenhum'}

MOVIMENTAÇÕES DE ADVERSÁRIOS:
${latestReport.adversary_movements?.map(a => `• ${a.entity}: ${a.movement} [ameaça: ${a.threat_level}]`).join('\n') || 'Nenhuma'}

CRISES POTENCIAIS:
${latestReport.crisis_alerts?.map(c => `• [${c.severity}] ${c.description} → ${c.action_required}`).join('\n') || 'Nenhuma'}

RECOMENDAÇÕES:
${latestReport.recommendations?.map(r => `• [${r.urgency}] ${r.action} (prazo: ${r.deadline_hours}h)`).join('\n') || 'Nenhuma'}

SUGESTÕES DE PAUTA:
${latestReport.agenda_suggestions?.map(s => `• ${s.title} | Tom: ${s.recommended_tone} | Público: ${s.target_audience}`).join('\n') || 'Nenhuma'}`;
}

// --- Bloco de alertas ---
// O coletor grava o mesmo alerta várias vezes com justificativas diferentes:
// sem dedupe, 8 dos 15 slots iam para uma notícia só.
const vistosAlerta = new Set();
const alertsUnicos = alerts.filter(a => {
  const k = (a.title || '') + '|' + (a.description || '').slice(0, 80);
  if (vistosAlerta.has(k)) return false;
  vistosAlerta.add(k);
  return true;
});

const criticalAlerts = alerts.filter(a => a.severity === 'critical' || a.severity === 'high');
let alertsContext = 'Nenhum alerta ativo.';
if (alertsUnicos.length > 0) {
  alertsContext = alertsUnicos.slice(0, 15).map(a => `• [${(a.severity||'').toUpperCase()}] ${a.title}: ${a.description}`).join('\n');
}

// --- Bloco de menções ---
let mentionsContext = 'Nenhuma menção encontrada no período.';
if (mentions.length > 0) {
  // O Radar precisa de matéria-prima: com 10 manchetes o modelo tenta
  // completar as narrativas sozinho.
  const maxNews = ctx.classification?.intent === 'RADAR' ? 50 : 10;
  const newsItems = mentions.filter(m => m.source === 'news').slice(0, maxNews);
  const socialItems = mentions.filter(m => m.source !== 'news').slice(0, 10);

  let blocks = [];

  if (newsItems.length > 0) {
    blocks.push('NOTÍCIAS:');
    newsItems.forEach(m => {
      const meta = typeof m.metadata === 'string' ? (JSON.parse(m.metadata || '{}')) : (m.metadata || {});
      blocks.push(`• [${(m.sentiment||'neutral').toUpperCase()}] ${m.title} | Fonte: ${meta.source_name || m.source} | Impacto: ${meta.impact_score || 'N/A'} | ${m.published_at?.substring(0,10) || ''} | ${m.url || ''}`);
      if (meta.summary) blocks.push(`  Resumo: ${meta.summary}`);
    });
  }

  if (socialItems.length > 0) {
    blocks.push('\nREDES SOCIAIS / COMENTÁRIOS:');
    socialItems.forEach(m => {
      const meta = typeof m.metadata === 'string' ? (JSON.parse(m.metadata || '{}')) : (m.metadata || {});
      blocks.push(`• [${(m.sentiment||'neutral').toUpperCase()}] ${m.title || m.content?.substring(0, 120) || ''} | Plataforma: ${m.source} | Entidade: ${m.entity_name || 'N/A'}`);
    });
  }

  mentionsContext = blocks.join('\n');
}

// --- Entidades ---
const candidateEntity = entities.find(e => e.entity_type === 'candidate');
const opponents = entities.filter(e => e.entity_type === 'opponent');
const entitiesContext = `Candidato: ${candidateEntity?.name || campaign.candidate_name || 'N/A'}
Adversários: ${opponents.map(o => o.name).join(', ') || 'Nenhum'}
Total monitoradas: ${entities.length}`;

const igRows = pegar('Buscar Instagram Insights', 'Buscar Instagram').map(i => i.json);
// --- Bloco de Instagram (insights de conta, coletor Windsor) ---
let instagramContext = 'Sem dados de Instagram disponíveis.';
if (igRows.length) {
  const latest = igRows[0];
  const prev = igRows[1];
  const nf = (v) => Number(v || 0).toLocaleString('pt-BR');
  const pct = (a, b) => (b && Number(b) > 0) ? Math.round((Number(a) - Number(b)) / Number(b) * 100) : null;
  const reachDelta = prev ? pct(latest.reach, prev.reach) : null;
  const engDelta = prev ? pct(latest.accounts_engaged, prev.accounts_engaged) : null;
  const trend = [...igRows].reverse().map(d => `• ${d.date}: alcance ${nf(d.reach)}, contas engajadas ${nf(d.accounts_engaged)}`).join('\n');
  instagramContext = `Conta: @${latest.user_name || 'N/A'}
Seguidores: ${nf(latest.followers_count)}
Seguindo: ${nf(latest.follows_count)}
Publicações: ${nf(latest.media_count)}
Alcance (último dia — ${latest.date}): ${nf(latest.reach)}${reachDelta != null ? ` (${reachDelta >= 0 ? '+' : ''}${reachDelta}% vs. dia anterior)` : ''}
Contas engajadas (último dia): ${nf(latest.accounts_engaged)}${engDelta != null ? ` (${engDelta >= 0 ? '+' : ''}${engDelta}% vs. dia anterior)` : ''}

Tendência (7 dias):
${trend}`;
}

// --- AGREGADOS DO RADAR ---
// Números do Radar Temático saem daqui, calculados em JavaScript. O modelo
// recebe o bloco pronto e só narra: contagem feita por LLM vira estimativa.
const normTema = s => (s || '').normalize('NFD').replace(/\p{Diacritic}/gu, '').toLowerCase().trim();
const temasMap = new Map();
const portaisMap = new Map();
mentions.forEach(m => {
  const meta = typeof m.metadata === 'string' ? (JSON.parse(m.metadata || '{}')) : (m.metadata || {});
  (meta.principais_temas || []).forEach(t => {
    const k = normTema(t);
    if (!k) return;
    // Guarda o rótulo da primeira ocorrência: "Eleições 2026" e "eleições 2026"
    // são o mesmo tema e precisam somar num item só.
    const cur = temasMap.get(k) || { label: t, n: 0 };
    cur.n++;
    temasMap.set(k, cur);
  });
  const portal = meta.source_name || m.source;
  portaisMap.set(portal, (portaisMap.get(portal) || 0) + 1);
});
const somaTemas = [...temasMap.values()].reduce((a, b) => a + b.n, 0) || 1;
const pctSent = k => total ? Math.round((sentCount[k] || 0) / total * 100) : 0;
const sovLinhas = [...temasMap.values()].sort((a, b) => b.n - a.n).slice(0, 10)
  .map(t => `${t.label} — ${Math.round(t.n / somaTemas * 100)}% (${t.n} menções)`).join('\n') || 'Sem temas classificados no período.';
const portalLinhas = [...portaisMap.entries()].sort((a, b) => b[1] - a[1]).slice(0, 10)
  .map(([p, n]) => `${p}: ${n}`).join('\n') || 'Nenhum portal no período.';
const janelaLabel = { '24 hours': '24 horas', '48 hours': '48 horas', '7 days': '7 dias', '30 days': '30 dias', '365 days': '12 meses' }[ctx.sql_interval] || ctx.sql_interval;
// total_periodo vem do COUNT(*) OVER(): o volume real, não o do lote.
const totalPeriodo = mentions[0]?.total_periodo ?? total;
const radarContext = `JANELA ANALISADA: últimas ${janelaLabel}
MENÇÕES DE IMPRENSA NO PERÍODO: ${totalPeriodo}
AMOSTRA ANALISADA (base dos temas e portais abaixo): ${total} matérias
SENTIMENTO POR VOLUME: positivo ${pctSent('positive')}% | neutro ${pctSent('neutral')}% | negativo ${pctSent('negative')}%

SHARE OF VOICE POR TEMA:
${sovLinhas}

PORTAIS MAIS ATIVOS:
${portalLinhas}

FONTES DISPONÍVEIS NESTE CICLO: imprensa (news/portal_rss) e Instagram da conta própria.
NÃO HÁ dados de alcance, engajamento por peça, Facebook, X/Twitter, YouTube, TikTok ou Bluesky.`;


// --- Instrução por intenção (usada quando o prompt está num Basic LLM Chain,
// que não passa pelo nó "Construir System Prompt") ---
const INSTRUCOES = {
  RADAR: 'Produza o Radar Temático do período, no formato definido no system. Todo número vem do bloco AGREGADOS: não recalcule nem estime. Não cite alcance, engajamento por peça ou plataformas sem coleta (Facebook, X, YouTube, TikTok, Bluesky). Manchetes e links só da lista NOTÍCIAS.',
  ADVERSARY: 'Foque no adversário perguntado: movimentação, exposição, ataques e risco eleitoral.',
  MEDIA: 'Analise a cobertura de imprensa: padrões, portais mais ativos, narrativas dominantes e impacto reputacional.',
  SOCIAL: 'Analise o que aparece de redes sociais e comentários: críticas recorrentes, elogios e humor do eleitorado.',
  CONTENT: 'Crie o conteúdo pedido e entregue pronto para uso, sem estrutura analítica em tópicos.',
  STRATEGY: 'Recomendações acionáveis para hoje: o que fazer, quando e por quê.',
  INTELLIGENCE: 'Análise de inteligência completa: riscos críticos, crises emergentes e movimentação de adversários.',
  GENERAL: 'Responda como consultor político sênior, com os dados disponíveis.',
};
const intentAtual = ctx.classification?.intent || 'GENERAL';
const instrucao = (INSTRUCOES[intentAtual] || INSTRUCOES.GENERAL)
  + (intentAtual === 'RADAR' ? '' : '\nQuando fizer sentido: 1. DIAGNÓSTICO 2. EVIDÊNCIAS 3. RISCOS 4. OPORTUNIDADES 5. RECOMENDAÇÕES (com prazo)');

console.log('[NEXO Assistant] Contexto montado | Menções: ' + total + ' | Alertas: ' + alerts.length + ' | Relatórios: ' + reports.length);

return [{
  json: {
    ...ctx,
    campaign,
    classification: ctx.classification,
    context: {
      report: reportContext,
      alerts: alertsContext,
      mentions: mentionsContext,
      entities: entitiesContext,
      instagram: instagramContext,
      radar: radarContext,
      stats: {
        total_mentions: total,
        sentiment: sentCount,
        critical_alerts: criticalAlerts.length,
        has_reports: reports.length > 0
      }
    },
    message: ctx.message || '',
    candidato: candidateEntity?.name || campaign.candidate_name || 'Ricardo Lima',
    intent: intentAtual,
    instrucao,
    noticias_bloco: mentionsContext,
    alertas_bloco: alertsContext,
    relatorio_bloco: reportContext,
    entidades_bloco: entitiesContext,
    instagram_bloco: instagramContext,
    radar_bloco: radarContext
  }
}];

const d = $input.first().json;
const campaign = d.campaign || {};
const classification = d.classification || {};
const ctx = d.context || {};
const stats = ctx.stats || {};

const intentInstructions = {
  INTELLIGENCE: 'Forneça uma análise de inteligência política completa. Priorize o relatório estratégico mais recente. Destaque riscos críticos, crises emergentes e movimentações de adversários.',
  MEDIA: 'Analise a cobertura midiática. Identifique padrões nas notícias, portais mais ativos, narrativas dominantes e o impacto na reputação do candidato.',
  SOCIAL: 'Analise os comentários e interações nas redes sociais. Identifique padrões de crítica, elogios recorrentes, temas que mobilizam e o humor predominante do eleitorado.',
  ADVERSARY: 'Foque nas movimentações dos adversários. Identifique estratégias, ataques, ganhos de exposição e riscos eleitorais associados.',
  CONTENT: `Crie o conteúdo solicitado: "${classification.content_type || classification.sub_intent}". Baseie-se nos dados disponíveis. O conteúdo deve ser estratégico, coerente com o momento político e pronto para uso imediato.`,
  STRATEGY: 'Elabore recomendações estratégicas acionáveis para hoje. Baseie-se nos dados disponíveis. Seja específico sobre o que fazer, quando e por quê.',
  RADAR: `Monte o Radar Temático do período no formato abaixo.

REGRAS INVIOLÁVEIS:
- Todo número vem do bloco AGREGADOS DO RADAR. Não recalcule, não estime, não arredonde para cima.
- É proibido citar alcance, engajamento por peça, seguidores ganhos ou qualquer métrica de Facebook, X/Twitter, YouTube, TikTok e Bluesky: não há coleta dessas fontes.
- Seção sem dado: escreva "sem coleta neste ciclo" e siga adiante. Nunca preencha por plausibilidade.
- Narrativas e manchetes saem exclusivamente das menções listadas, sempre com portal e link reais.

FORMATO:
*📡 Radar Temático — <candidato> · <janela analisada>*

*Visão geral do período*
📲 Menções de imprensa: <n>

*Sentimento por volume*
🟢 Positivo: <x>%
🟡 Neutro: <y>%
🔴 Negativo: <z>%

*📊 Temas e Share of Voice*
<uma linha por tema, como no bloco agregado>

*Narrativas Favoráveis*
<2 a 4 narrativas; cada uma com o frame entre aspas, o que sustenta o frame e os portais que a carregaram>

*Narrativas Desfavoráveis*
<mesmo formato>

*🗞️ Imprensa*
<manchete — portal>
<url>

*🔭 Olhar para as próximas horas*
<3 movimentos concretos: o ativo subexplorado, o risco que pode escalar e o fato novo que pede atenção>`,
  GENERAL: 'Responda à pergunta estratégica com base nos dados disponíveis. Atue como consultor político sênior.'
};

const intentGuidance = intentInstructions[classification.intent] || intentInstructions.GENERAL;

const systemPrompt = `Você é o NEXO Strategic Assistant.

Você é um consultor político de elite especializado em campanhas eleitorais brasileiras.
Sua missão é transformar dados em decisões estratégicas acionáveis.
Nunca invente dados. Sempre baseie suas respostas nos registros recuperados.
Quando não houver informação suficiente, deixe isso explícito.
Nunca se identifique como IA genérica. Você é o NEXO.
Tom: profissional, executivo, direto, consultivo.

CAMPANHA ATIVA:
Nome: ${campaign.name || 'N/A'}
Candidato: ${campaign.candidate_name || 'N/A'}
Região: ${campaign.target_region || 'N/A'}

ENTIDADES MONITORADAS:
${ctx.entities || ''}

ESTATÍSTICAS DO PERÍODO:
Menções analisadas: ${stats.total_mentions || 0}
Sentimento positivo: ${stats.sentiment?.positive || 0}
Sentimento neutro: ${stats.sentiment?.neutral || 0}
Sentimento negativo: ${stats.sentiment?.negative || 0}
Alertas críticos/altos: ${stats.critical_alerts || 0}
Relatórios disponíveis: ${stats.has_reports ? 'Sim' : 'Não'}

${ctx.report ? '=== INTELIGÊNCIA ESTRATÉGICA (RELATÓRIO MAIS RECENTE) ===\n' + ctx.report : ''}

=== ALERTAS ATIVOS ===
${ctx.alerts || 'Nenhum alerta.'}

=== DADOS DE MENÇÕES/NOTÍCIAS ===
${ctx.mentions || 'Nenhuma menção no período.'}

=== INSTAGRAM (INSIGHTS DA CONTA — FONTE: WINDSOR) ===
${ctx.instagram || 'Sem dados de Instagram.'}

${classification.intent === 'RADAR' ? '=== AGREGADOS DO RADAR (ÚNICA FONTE DE NÚMEROS) ===' : ''}
${classification.intent === 'RADAR' ? (ctx.radar || 'Sem agregados.') : ''}

=== INSTRUÇÃO PARA ESTA CONSULTA ===
${intentGuidance}

Estrutura da resposta quando relevante:
1. DIAGNÓSTICO — situação atual em 2-3 frases diretas
2. EVIDÊNCIAS — dados que embasam a análise
3. RISCOS — o que pode piorar e por quê
4. OPORTUNIDADES — o que pode ser aproveitado
5. RECOMENDAÇÕES — ações específicas com prazos

